begin;
select no_plan();
select has_table('public','payments','recebimentos existem');
select has_function('public','record_payment',array['uuid','bigint','timestamp with time zone','text','uuid'],'RPC de recebimento existe');
insert into auth.users(id) values('71000000-0000-0000-0000-000000000001'),('71000000-0000-0000-0000-000000000002');
insert into public.profiles values('71000000-0000-0000-0000-000000000001','owner'),('71000000-0000-0000-0000-000000000002','driver');
insert into public.customers(id,name,address,weekday,position) values('72000000-0000-0000-0000-000000000001','Conta fictícia A','Rua fictícia',2,1),('72000000-0000-0000-0000-000000000002','Conta fictícia B','Rua fictícia',2,2);
select set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000001',true);
set local role authenticated;
savepoint advance_case;
select is(public.record_payment('72000000-0000-0000-0000-000000000001',10000,'2026-09-01T12:00Z','pix','73000000-0000-0000-0000-000000000001')->>'creditCents','10000','adiantamento vira crédito');
select is(public.record_payment('72000000-0000-0000-0000-000000000001',10000,'2026-09-01T12:00Z','pix','73000000-0000-0000-0000-000000000001')->>'creditCents','10000','replay preserva resposta');
select is((select count(*) from public.payments),1::bigint,'replay não duplica caixa');
select throws_ok($$select public.record_payment('72000000-0000-0000-0000-000000000001',1,'2026-09-01T12:00Z','pix','73000000-0000-0000-0000-000000000001')$$,'22023','Request conflict','mesmo ID não aceita valor divergente');
reset role;
insert into public.sales(id,customer_id,amount_cents,eggs,cost_cents,effective_at,actor_id) values('74000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000001',3300,30,1000,'2026-09-02T12:00Z','71000000-0000-0000-0000-000000000001');
select private.apply_customer_credit('72000000-0000-0000-0000-000000000001');
set local role authenticated;
select is(public.get_customer_account('72000000-0000-0000-0000-000000000001')->>'openCents','0','venda consome crédito');
select is(public.get_customer_account('72000000-0000-0000-0000-000000000001')->>'creditCents','6700','10000 menos 3300 deixa6700');
select is((select sum(amount_cents) from public.payments),10000::numeric,'uso de crédito não cria caixa');
rollback to advance_case;
reset role;
insert into public.sales(id,customer_id,amount_cents,eggs,cost_cents,effective_at,actor_id) values('74000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000001',3300,30,1000,'2026-09-01T12:00Z','71000000-0000-0000-0000-000000000001'),('74000000-0000-0000-0000-000000000002','72000000-0000-0000-0000-000000000001',3300,30,1000,'2026-09-02T12:00Z','71000000-0000-0000-0000-000000000001');
set local role authenticated;
select is(public.record_payment('72000000-0000-0000-0000-000000000001',5000,'2026-10-01T12:00Z','cash','73000000-0000-0000-0000-000000000002')->>'openCents','1600','duas vendas menos parcial deixam1600');
select is((select amount_cents from public.payment_allocations where sale_id='74000000-0000-0000-0000-000000000001'),3300::bigint,'FIFO quita venda mais antiga');
select is((select amount_cents from public.payment_allocations where sale_id='74000000-0000-0000-0000-000000000002'),1700::bigint,'FIFO aplica restante à segunda');
select is(public.get_customer_account('72000000-0000-0000-0000-000000000002')->>'creditCents','0','outro cliente não recebe crédito');
select is((public.get_customer_account('72000000-0000-0000-0000-000000000001')->'sales'->0->>'dueAt'),null::text,'sem prazo não inventa atraso');
savepoint correction_case;
select set_config('test.payment_known_at',clock_timestamp()::text,true);
select public.correct_payment((select id from public.payments limit 1),'{"amountCents":1000,"method":"pix"}','Valor digitado incorretamente','73000000-0000-0000-0000-000000000003');
select is(public.get_customer_account('72000000-0000-0000-0000-000000000001')->>'openCents','5600','correção libera dívida e realoca substituto');
select is((select count(*) from public.payments),3::bigint,'original reversão e substituto preservados');
select is((select count(*) from public.payment_allocations where reversal_of is not null),2::bigint,'alocações desfeitas têm contraeventos');
select is((select sum(amount_cents) from public.payments where reversal_of is null and replacement_of is null),5000::numeric,'original não alterado');
select ok((select bool_and(received_at>'2026-10-01T12:00Z') from public.payments where reversal_of is not null or replacement_of is not null),'correções usam data atual');
select is((select sum(case when reversal_of is null then amount_cents else -amount_cents end) from public.payments where received_at<'2026-10-02T00:00Z'),5000::numeric,'período anterior conserva recebimento original');
select is((select sum(case when reversal_of is null then amount_cents else -amount_cents end) from public.payments where created_at<=current_setting('test.payment_known_at')::timestamptz),5000::numeric,'corte de conhecimento reproduz emissão anterior');
select is((select sum(case when reversal_of is null then amount_cents else -amount_cents end) from public.payments),1000::numeric,'posição atual soma original reversão e substituto');
select is((select sum(amount_cents) from public.sales),6600::numeric,'correção monetária não altera ovos/vendas');
rollback to correction_case;
select public.correct_payment((select id from public.payments limit 1),null,'Lançamento duplicado fictício','73000000-0000-0000-0000-000000000004');
select is(public.get_customer_account('72000000-0000-0000-0000-000000000001')->>'openCents','6600','sem substituto reapresenta dívida integral');
select throws_ok($$select public.correct_payment((select id from public.payments where reversal_of is null limit 1),null,'Repetido',gen_random_uuid())$$,'PT409','PAYMENT_ALREADY_CORRECTED','segunda correção rejeitada');
savepoint opening_case;
select public.set_opening_balance('72000000-0000-0000-0000-000000000002',3300,'2026-08-01','Dívida inicial fictícia','73000000-0000-0000-0000-000000000005');
select is(public.record_payment('72000000-0000-0000-0000-000000000002',1000,'2026-10-01T12:00Z','pix',gen_random_uuid())->>'openCents','2300','abertura de dívida aceita quitação');
select throws_ok($$select public.set_opening_balance('72000000-0000-0000-0000-000000000002',100,'2026-08-01','Alterar',gen_random_uuid())$$,'PT409','OPENING_LOCKED','abertura após movimentos bloqueada');
rollback to opening_case;
select public.set_opening_balance('72000000-0000-0000-0000-000000000002',-10000,'2026-08-01','Crédito inicial fictício',gen_random_uuid());
select is(public.get_customer_account('72000000-0000-0000-0000-000000000002')->>'creditCents','10000','abertura negativa cria crédito');
select is((select count(*) from public.payments where customer_id='72000000-0000-0000-0000-000000000002'),0::bigint,'crédito inicial não é caixa');
select public.set_opening_balance('72000000-0000-0000-0000-000000000002',-2000,'2026-08-01','Correção antes de operar',gen_random_uuid());
select is(public.get_customer_account('72000000-0000-0000-0000-000000000002')->>'creditCents','2000','abertura substituída antes de movimentos');
select is((select sum(case when reversal_of is null then signed_cents else -signed_cents end) from public.customer_openings where customer_id='72000000-0000-0000-0000-000000000002' and effective_at<'2026-09-01'),-10000::numeric,'correção da abertura não altera posição histórica');
select throws_ok($$select public.record_payment('72000000-0000-0000-0000-000000000002',9007199254740992,now(),'pix',gen_random_uuid())$$,'22003','AMOUNT_OUT_OF_RANGE','valor inseguro rejeitado');
select throws_ok($$select public.record_payment('72000000-0000-0000-0000-000000000002',0,now(),'pix',gen_random_uuid())$$,'22023','INVALID_INPUT','zero rejeitado');
select throws_ok($$update public.payments set amount_cents=1$$,'42501',null,'dona não altera livro diretamente');
select throws_ok($$delete from public.payment_allocations$$,'42501',null,'dona não apaga alocações');
select is(public.reconcile_payment_request('73000000-0000-0000-0000-000000000099','record_payment')->>'status','closed','reconciliação encerra tentativa ausente');
select throws_ok($$select public.record_payment('72000000-0000-0000-0000-000000000002',1,now(),'pix','73000000-0000-0000-0000-000000000099')$$,'55000','REQUEST_CLOSED','tentativa encerrada não salva atrasado');
select set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000002',true);
select is((select count(*) from public.payments),0::bigint,'motorista não lê recebimentos');
select throws_ok($$select public.get_customer_account('72000000-0000-0000-0000-000000000001')$$,'42501','FORBIDDEN','motorista não lê conta');
select throws_ok($$select public.record_payment('72000000-0000-0000-0000-000000000001',1,now(),'pix',gen_random_uuid())$$,'42501','FORBIDDEN','motorista não registra recebimento');
reset role;
select throws_ok($$insert into public.payment_allocations(customer_id,payment_id,sale_id,amount_cents,actor_id) values('72000000-0000-0000-0000-000000000002',(select id from public.payments where reversal_of is null limit 1),'74000000-0000-0000-0000-000000000001',1,'71000000-0000-0000-0000-000000000001')$$,'23514','CUSTOMER_MISMATCH','alocação entre clientes bloqueada no banco');
set local role anon;
select throws_ok($$select public.get_customer_balances()$$,'42501',null,'anônimo não lê saldos');
reset role;
select * from finish();
rollback;
